uint8_t predict_waveform(const float* features) {
    float votes[4] = {0};  // sine, square, triangle, other
    for (int t=0; t<N_TREES; t++) {
        int node = 0;
        const DecisionTree* tree = &trees[t];
        while (node >= 0) {
            if (features[tree->feature[node]] <= tree->threshold[node]) {
                node = tree->children_left[node];
            } else {
                node = tree->children_right[node];
            }
        }
        node = -node - 1;
        int class_id = (int)tree->value[node];
        if (class_id >= 0 && class_id < 4) votes[class_id] += 1.0f;
    }
    uint8_t best_class = 0;
    float best_vote = votes[0];
    for (int i=1; i<4; i++) {
        if (votes[i] > best_vote) { best_vote = votes[i]; best_class = i; }
    }
    return best_class;  // 0=sine, 1=square, 2=triangle, 3=other
}
